const GanttGridHeaderCell = ({
    label,
    tooltip = null,
    align = 'left',
    sticky = false,
    stickyLeft = 0,
    stickyZIndex = 0,
}) => {
    const alignmentClass = align === 'right'
        ? 'justify-end text-right'
        : align === 'center'
            ? 'justify-center text-center'
            : 'justify-start text-left';
    const stickyClassName = sticky
        ? 'sticky border-r border-[#ececec]'
        : '';
    const contentNode = (
        <div
            className={`flex min-h-[54px] items-center bg-[#f2f2f0] px-4 py-1.5 text-[10px] font-black uppercase tracking-[0.18em] text-zinc-500 ${alignmentClass} ${stickyClassName}`}
            style={sticky ? { left: `${stickyLeft}px`, zIndex: stickyZIndex } : undefined}
        >
            <span className="truncate">{label}</span>
        </div>
    );

    if (!tooltip) {
        return contentNode;
    }

    return (
        <GanttHeaderTooltip content={tooltip}>
            {contentNode}
        </GanttHeaderTooltip>
    );
};

const GanttDataGridHeaderCells = ({
    selectedDurationDisplayOption,
    columnWidths = DEFAULT_GRID_COLUMN_WIDTHS,
    columns = buildGanttColumnDefinitions(columnWidths),
}) => {
    const visibleColumns = columns.map((column) => ({
        ...column,
        tooltip: column.id === 'duration_type'
            ? `Magnitud visual aplicada por fila a la lectura de duración del Gantt. Predeterminada: ${selectedDurationDisplayOption.label}.`
            : column.id === 'predecessors'
                ? GANTT_PREDECESSOR_SHORTCODE_TOOLTIP
                : column.tooltip,
    }));

    return (
        <>
            {visibleColumns.map((column, index) => (
                <GanttGridHeaderCell
                    key={column.id || column.label}
                    label={column.label}
                    tooltip={column.tooltip}
                    sticky={column.locked}
                    stickyLeft={column.locked ? resolveStickyGridColumnLeft(columnWidths, index) : 0}
                    stickyZIndex={index === 0 ? 146 : 145}
                />
            ))}
        </>
    );
};

const GanttHeaderTooltip = ({ content, children, disabled = false }) => (
    <AppHint
        content={content}
        disabled={disabled}
        tone="light"
        as="div"
        triggerClassName="contents"
        maxWidth={260}
        widthOffset={52}
    >
        {children}
    </AppHint>
);

const WEEKDAY_LABELS = ['L', 'M', 'X', 'J', 'V', 'S', 'D'];
const MONTH_LABELS = [
    'Enero',
    'Febrero',
    'Marzo',
    'Abril',
    'Mayo',
    'Junio',
    'Julio',
    'Agosto',
    'Septiembre',
    'Octubre',
    'Noviembre',
    'Diciembre',
];

const toCalendarIsoDate = (value) => {
    const normalized = normalizeDate(value);
    if (!normalized) return '';
    const year = normalized.getFullYear();
    const month = String(normalized.getMonth() + 1).padStart(2, '0');
    const day = String(normalized.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
};

const getCalendarMonthStart = (value) => {
    const dateValue = normalizeDate(value);
    if (!dateValue) return null;
    return new Date(dateValue.getFullYear(), dateValue.getMonth(), 1);
};

const getCalendarMonthEnd = (value) => {
    const dateValue = normalizeDate(value);
    if (!dateValue) return null;
    return new Date(dateValue.getFullYear(), dateValue.getMonth() + 1, 0);
};

const addCalendarDays = (value, days) => {
    const dateValue = normalizeDate(value);
    if (!dateValue) return null;
    const next = new Date(dateValue);
    next.setDate(next.getDate() + Number(days || 0));
    return next;
};

const getCalendarWeekdayIndex = (value) => {
    const dateValue = normalizeDate(value);
    if (!dateValue) return 0;
    return (dateValue.getDay() + 6) % 7;
};

const buildHolidayCalendarTooltip = (items = []) => {
    if (!items.length) return '';
    return items.map((item) => {
        const badges = [
            item.scope_label || 'Proyecto',
            item.origin_type === 'manual_add' ? 'Manual' : 'Oficial',
        ].filter(Boolean).join(' · ');
        return [
            `${item.holiday_name}${badges ? ` (${badges})` : ''}`,
            item.source_name ? `Fuente: ${item.source_name}` : null,
            item.notes || null,
        ].filter(Boolean).join('\n');
    }).join('\n\n');
};

const buildHolidayCalendarMonths = (startValue, endValue, config, items = []) => {
    const startDate = normalizeDate(startValue);
    const endDate = normalizeDate(endValue);
    if (!startDate || !endDate) return [];

    const normalizedStart = new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate());
    const normalizedEnd = new Date(endDate.getFullYear(), endDate.getMonth(), endDate.getDate());
    const workdaysPerWeek = Math.min(7, Math.max(1, Math.round(Number(config?.dias_laborables_semana || 5))));
    const holidayMap = new Map();
    const projectStartIso = toCalendarIsoDate(normalizedStart);
    const projectEndIso = toCalendarIsoDate(normalizedEnd);
    const todayIso = toCalendarIsoDate(new Date());

    (items || []).forEach((item) => {
        const key = toCalendarIsoDate(item?.observed_date);
        if (!key) return;
        const bucket = holidayMap.get(key) || [];
        bucket.push(item);
        holidayMap.set(key, bucket);
    });

    const months = [];
    let cursor = getCalendarMonthStart(normalizedStart);
    const endMonth = getCalendarMonthStart(normalizedEnd);
    let safety = 0;

    while (cursor && endMonth && cursor <= endMonth && safety < 24) {
        const monthStart = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
        const monthEnd = getCalendarMonthEnd(cursor);
        const firstVisible = addCalendarDays(monthStart, -getCalendarWeekdayIndex(monthStart));
        const lastVisible = addCalendarDays(monthEnd, 6 - getCalendarWeekdayIndex(monthEnd));
        const days = [];

        for (
            let dayCursor = new Date(firstVisible.getFullYear(), firstVisible.getMonth(), firstVisible.getDate());
            dayCursor <= lastVisible;
            dayCursor = addCalendarDays(dayCursor, 1)
        ) {
            const isoDate = toCalendarIsoDate(dayCursor);
            const dayItems = holidayMap.get(isoDate) || [];
            const weekdayIndex = getCalendarWeekdayIndex(dayCursor);
            const inMonth = dayCursor.getMonth() === monthStart.getMonth();
            const inWindow = dayCursor >= normalizedStart && dayCursor <= normalizedEnd;
            const isHoliday = dayItems.length > 0;
            const isWorkdayBase = weekdayIndex < workdaysPerWeek;
            const manualHolidayCount = dayItems.filter((item) => item.origin_type === 'manual_add').length;
            const officialHolidayCount = Math.max(0, dayItems.length - manualHolidayCount);

            days.push({
                isoDate,
                date: new Date(dayCursor.getFullYear(), dayCursor.getMonth(), dayCursor.getDate()),
                label: dayCursor.getDate(),
                inMonth,
                inWindow,
                isHoliday,
                isWorkday: inWindow && isWorkdayBase && !isHoliday,
                isNonWorking: inWindow && (!isWorkdayBase || isHoliday),
                isWeeklyNonWorking: inWindow && !isWorkdayBase,
                isManualHoliday: manualHolidayCount > 0,
                isOfficialHoliday: officialHolidayCount > 0,
                manualHolidayCount,
                officialHolidayCount,
                isProjectStart: isoDate === projectStartIso,
                isProjectEnd: isoDate === projectEndIso,
                isToday: isoDate === todayIso,
                projectDayIndex: inWindow ? Math.round((dayCursor.getTime() - normalizedStart.getTime()) / DAY_MS) + 1 : null,
                holidayItems: dayItems,
                tooltip: buildHolidayCalendarTooltip(dayItems),
            });
        }

        months.push({
            key: `${monthStart.getFullYear()}-${String(monthStart.getMonth() + 1).padStart(2, '0')}`,
            label: `${MONTH_LABELS[monthStart.getMonth()]} ${monthStart.getFullYear()}`,
            days,
        });

        cursor = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 1);
        safety += 1;
    }

    return months;
};

function normalizeDate(value) {
    if (!value) return null;
    if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
    const normalized = String(value).trim();
    const ddmmyyyy = normalized.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    if (ddmmyyyy) {
        const [, d, m, y] = ddmmyyyy;
        const parsed = new Date(Number(y), Number(m) - 1, Number(d));
        return Number.isNaN(parsed.getTime()) ? null : parsed;
    }
    const yyyymmdd = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (yyyymmdd) {
        const [, y, m, d] = yyyymmdd;
        const parsed = new Date(Number(y), Number(m) - 1, Number(d));
        return Number.isNaN(parsed.getTime()) ? null : parsed;
    }
    const parsed = new Date(normalized);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
}

const parseOptionalNumericValue = (value) => {
    if (value === null || value === undefined || value === '') return null;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
};

const resolvePreferredIndirectPercent = (...candidates) => {
    for (const candidate of candidates) {
        const parsed = parseOptionalNumericValue(candidate);
        if (parsed !== null && parsed >= 0) return parsed;
    }
    return 0;
};

const formatCronogramaDescripcion = (row) => {
    if (!row?.descripcion) return '';
    return row.is_calculable
        ? normalizeDescriptionCapitalization(row.descripcion)
        : normalizeSubcategoryDisplay(row.descripcion);
};

const formatDate = (value) => {
    const parsed = normalizeDate(value);
    if (!parsed) return 'Sin fecha';
    return `${String(parsed.getDate()).padStart(2, '0')}/${String(parsed.getMonth() + 1).padStart(2, '0')}/${parsed.getFullYear()}`;
};

const formatDateTime = (value) => {
    const parsed = value ? new Date(value) : null;
    if (!parsed || Number.isNaN(parsed.getTime())) return 'Sin fecha';
    return `${formatDate(parsed)} ${String(parsed.getHours()).padStart(2, '0')}:${String(parsed.getMinutes()).padStart(2, '0')}`;
};

const formatDateRangeCompact = (startValue, endValue) => {
    const start = normalizeDate(startValue);
    const end = normalizeDate(endValue);
    if (!start && !end) return 'Sin ventana';
    if (start && !end) {
        return `${String(start.getDate()).padStart(2, '0')}/${String(start.getMonth() + 1).padStart(2, '0')}`;
    }
    if (!start && end) {
        return `${String(end.getDate()).padStart(2, '0')}/${String(end.getMonth() + 1).padStart(2, '0')}`;
    }
    return `${String(start.getDate()).padStart(2, '0')}/${String(start.getMonth() + 1).padStart(2, '0')}-${String(end.getDate()).padStart(2, '0')}/${String(end.getMonth() + 1).padStart(2, '0')}`;
};

const openDurationGovernanceAlert = () => appAlert({
    title: 'Duración gobernada por recursos',
    message: GANTT_DURATION_POLICY_MESSAGE,
    tone: 'info',
});

const toNativeDate = (value) => {
    const parsed = normalizeDate(value);
    if (!parsed) return '';
    return `${parsed.getFullYear()}-${String(parsed.getMonth() + 1).padStart(2, '0')}-${String(parsed.getDate()).padStart(2, '0')}`;
};

const formatNumber = (value, decimals = 2) => new Intl.NumberFormat('es-ES', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
}).format(Number(value || 0));

const formatMovementDelta = (deltaDays, config = {}) => {
    const safeDelta = Math.abs(Number(deltaDays || 0));
    if (!Number.isFinite(safeDelta) || safeDelta < 0.000001) {
        return 'Sin movimiento efectivo';
    }
    const dailyHours = Math.max(1, Number(config?.jornada_laboral_horas || 8));
    const totalMinutes = Math.max(1, Math.round(safeDelta * dailyHours * 60));
    const minutesPerDay = dailyHours * 60;
    if (totalMinutes < minutesPerDay) {
        const hours = Math.floor(totalMinutes / 60);
        const minutes = totalMinutes % 60;
        if (hours > 0 && minutes > 0) return `${hours} h ${minutes} min mov.`;
        if (hours > 0) return `${hours} h mov.`;
        return `${minutes} min mov.`;
    }
    return `${formatNumber(safeDelta, 2)} d mov.`;
};

const resolveGanttSlackValue = (planningNode = null, diagnostics = null, kind = 'total') => {
    const key = kind === 'free' ? 'freeSlack' : 'totalSlack';
    const value = Number(planningNode?.[key] ?? diagnostics?.[key]);
    return Number.isFinite(value) ? value : null;
};

const GanttSlackCell = ({ value, label }) => {
    const hasValue = Number.isFinite(Number(value));
    const numericValue = hasValue ? Number(value) : null;
    const isNegative = hasValue && numericValue < -0.0001;
    const isCritical = hasValue && !isNegative && Math.abs(numericValue) <= 0.0001;
    const className = isNegative
        ? 'border-rose-200 bg-rose-50 text-rose-700'
        : isCritical
            ? 'border-[#F39200]/28 bg-[#fff7ed] text-[#F39200]'
            : 'border-sky-100 bg-sky-50 text-[#136191]';
    const tooltip = hasValue
        ? `${label}: ${formatNumber(numericValue, 2)} d${isNegative ? '\nHolgura negativa detectada' : isCritical ? '\nTarea crítica o sin margen' : ''}`
        : `${label}: no disponible para esta línea`;

    return (
        <GanttHeaderTooltip content={tooltip}>
            <span className={`inline-flex w-full items-center justify-end rounded-[0.75rem] border px-2 py-1.5 text-[10px] font-black ${className}`}>
                {hasValue ? `${formatNumber(numericValue, 2)} d` : '--'}
            </span>
        </GanttHeaderTooltip>
    );
};

const formatCurrency = (value, currency = 'USD', decimals = 2) => new Intl.NumberFormat('es-ES', {
    style: 'currency',
    currency,
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
}).format(Number(value || 0));

