const buildEquipmentOwnershipGapMessage = (source = null) => {
    if (!source?.equipment_cost_traceability_gap) return '';
    return 'El costo de Equipos y Herramientas sigue en modo proxy porque la capa clásica todavía no distingue equipo propio inactivo vs equipo alquilado activo.';
};

const buildCrashingBlockerMessage = (source = null) => {
    if (!source?.blocked_for_real_crashing) return '';
    if (source?.blocking_reason === 'pending_equipment_ownership_model') {
        return 'Pendiente para crashing económico real: falta modelar ownership clásico de equipos (`propio` vs `alquilado`).';
    }
    return 'Pendiente para crashing económico real por datos clásicos faltantes.';
};

const getEconomicConfidenceBadge = (source = null) => {
    if (source?.economic_confidence_level === 'traceable') {
        return { label: 'Trazable', tone: 'emerald' };
    }
    if (source?.economic_confidence_level === 'proxy_equipment' || source?.equipment_cost_traceability_gap) {
        return { label: 'Proxy equipos', tone: 'amber' };
    }
    return null;
};

const resolveGanttCostPreview = (row = null, draft = {}, effectiveRow = null) => {
    const costModel = resolveGanttCostModel(row, draft);
    if (!row?.is_calculable || !costModel) return null;

    const baseDurationDays = Number(row?.dias_calendario ?? row?.dias_utiles ?? 0);
    const visibleDurationDays = Number(
        effectiveRow?.dias_calendario
        ?? effectiveRow?.dias_utiles
        ?? getGanttRowDuration(row, draft)
        ?? 0
    );
    const temporalCostPerDay = Number(costModel.temporal_cost_per_day ?? 0);
    const quantityDependentCost = Number(costModel.quantity_dependent_cost ?? 0);
    const baseTemporalCost = Number(costModel.time_dependent_cost ?? 0);
    const visibleTemporalCost = Math.max(0, temporalCostPerDay * Math.max(0, visibleDurationDays));
    const visibleLineCost = quantityDependentCost + visibleTemporalCost;
    const baseLineCost = Number(costModel.line_direct_cost ?? (quantityDependentCost + baseTemporalCost));

    return {
        baseDurationDays,
        visibleDurationDays,
        temporalCostPerDay,
        baseTemporalCost,
        visibleTemporalCost,
        quantityDependentCost,
        baseLineCost,
        visibleLineCost,
        temporalDelta: visibleTemporalCost - baseTemporalCost,
        totalDelta: visibleLineCost - baseLineCost,
        durationDelta: visibleDurationDays - baseDurationDays,
    };
};

const resolveGanttBudgetPricePreview = (
    row = null,
    draft = {},
    effectiveRow = null,
    { indirectPercentage = 0, moneyDecimals = 2 } = {},
) => {
    const directPreview = resolveGanttCostPreview(row, draft, effectiveRow);
    if (!row?.is_calculable || !directPreview) return null;

    const quantity = parseOptionalNumericValue(row?.cantidad) ?? 0;
    const baseDirectLineCost = Number(directPreview.baseLineCost ?? 0);
    const visibleDirectLineCost = Number(directPreview.visibleLineCost ?? 0);
    const baseDirectUnitCostRaw = quantity > 0
        ? (baseDirectLineCost / quantity)
        : Number(resolveGanttCostModel(row, draft)?.unit_direct_cost ?? 0);
    const visibleDirectUnitCostRaw = quantity > 0
        ? (visibleDirectLineCost / quantity)
        : baseDirectUnitCostRaw;
    const roundedBaseDirectUnitCost = roundDecimalNumber(baseDirectUnitCostRaw || 0, moneyDecimals);
    const roundedVisibleDirectUnitCost = roundDecimalNumber(visibleDirectUnitCostRaw || 0, moneyDecimals);
    const factor = 1 + (Math.max(0, Number(indirectPercentage || 0)) / 100);
    const baseFunctionalUnitPrice = roundDecimalNumber(
        multiplyDecimalNumber([baseDirectUnitCostRaw || 0, factor], { decimals: 6 }),
        moneyDecimals
    );
    const visibleFunctionalUnitPrice = roundDecimalNumber(
        multiplyDecimalNumber([visibleDirectUnitCostRaw || 0, factor], { decimals: 6 }),
        moneyDecimals
    );
    const baseBudgetLineTotal = roundDecimalNumber(
        multiplyDecimalNumber([quantity || 0, baseFunctionalUnitPrice || 0], { decimals: 6 }),
        moneyDecimals
    );
    const visibleBudgetLineTotal = roundDecimalNumber(
        multiplyDecimalNumber([quantity || 0, visibleFunctionalUnitPrice || 0], { decimals: 6 }),
        moneyDecimals
    );

    return {
        ...directPreview,
        indirectPercentage: Math.max(0, Number(indirectPercentage || 0)),
        quantity,
        roundedBaseDirectUnitCost,
        roundedVisibleDirectUnitCost,
        baseFunctionalUnitPrice,
        visibleFunctionalUnitPrice,
        baseBudgetLineTotal,
        visibleBudgetLineTotal,
        baseIndirectUnitPrice: roundDecimalNumber(baseFunctionalUnitPrice - roundedBaseDirectUnitCost, moneyDecimals),
        visibleIndirectUnitPrice: roundDecimalNumber(visibleFunctionalUnitPrice - roundedVisibleDirectUnitCost, moneyDecimals),
        budgetDelta: roundDecimalNumber(visibleBudgetLineTotal - baseBudgetLineTotal, moneyDecimals),
    };
};

const buildGanttApprovalCostSummary = (rows = [], drafts = {}, config = {}, options = {}) => {
    const initial = {
        apusWithCostModel: 0,
        baseLineCost: 0,
        visibleLineCost: 0,
        baseTemporalCost: 0,
        visibleTemporalCost: 0,
        totalDurationDelta: 0,
        increasedRows: 0,
        reducedRows: 0,
        unchangedRows: 0,
        topEntries: [],
    };

    const aggregated = (Array.isArray(rows) ? rows : []).reduce((acc, row) => {
        if (!row?.is_calculable) return acc;
        const lineId = String(row?.budget_line_id ?? row?.linea_id ?? '');
        const draft = drafts?.[lineId] || {};
        const effectiveRow = applyGanttRowDraft(row, draft, config);
        const preview = resolveGanttBudgetPricePreview(row, draft, effectiveRow, options);
        const costModel = resolveGanttCostModel(row, draft);
        if (!preview || !costModel) return acc;

        const totalDelta = roundConfigNumber(preview.budgetDelta ?? 0, 4);
        if (totalDelta > 0.0001) {
            acc.increasedRows += 1;
        } else if (totalDelta < -0.0001) {
            acc.reducedRows += 1;
        } else {
            acc.unchangedRows += 1;
        }

        acc.apusWithCostModel += 1;
        acc.baseLineCost += Number(preview.baseBudgetLineTotal ?? 0);
        acc.visibleLineCost += Number(preview.visibleBudgetLineTotal ?? 0);
        acc.baseTemporalCost += Number(preview.baseTemporalCost ?? 0);
        acc.visibleTemporalCost += Number(preview.visibleTemporalCost ?? 0);
        acc.totalDurationDelta += Number(preview.durationDelta ?? 0);
        acc.topEntries.push({
            id: lineId || String(acc.topEntries.length + 1),
            codigo: row?.codigo_item || `Línea ${lineId || '?'}`,
            descripcion: row?.descripcion || 'APU',
            totalDelta,
            temporalDelta: roundConfigNumber(preview.temporalDelta ?? 0, 4),
            visibleLineCost: roundConfigNumber(preview.visibleBudgetLineTotal ?? 0, 4),
            durationDelta: roundConfigNumber(preview.durationDelta ?? 0, 4),
            dominantTimeCategory: costModel?.dominant_time_category || 'N/D',
        });
        return acc;
    }, initial);

    const topEntries = aggregated.topEntries
        .sort((left, right) => Math.abs(right.totalDelta) - Math.abs(left.totalDelta))
        .slice(0, 3);

    return {
        apusWithCostModel: aggregated.apusWithCostModel,
        baseLineCost: roundConfigNumber(aggregated.baseLineCost, 4),
        visibleLineCost: roundConfigNumber(aggregated.visibleLineCost, 4),
        baseTemporalCost: roundConfigNumber(aggregated.baseTemporalCost, 4),
        visibleTemporalCost: roundConfigNumber(aggregated.visibleTemporalCost, 4),
        totalDelta: roundConfigNumber(aggregated.visibleLineCost - aggregated.baseLineCost, 4),
        temporalDelta: roundConfigNumber(aggregated.visibleTemporalCost - aggregated.baseTemporalCost, 4),
        totalDurationDelta: roundConfigNumber(aggregated.totalDurationDelta, 4),
        increasedRows: aggregated.increasedRows,
        reducedRows: aggregated.reducedRows,
        unchangedRows: aggregated.unchangedRows,
        topEntries,
    };
};

const buildGanttApprovalCrashingSummary = (rows = [], drafts = {}, planningMap = new Map()) => {
    const initial = {
        criticalRows: 0,
        reviewReadyRows: 0,
        totalDaysSaved: 0,
        totalTemporalRelease: 0,
        totalIncrementalResourceCostProxy: 0,
        totalNetCrashingCostDeltaProxy: 0,
        traceableRows: 0,
        equipmentOwnershipGapRows: 0,
        topEntries: [],
    };

    const aggregated = (Array.isArray(rows) ? rows : []).reduce((acc, row) => {
        if (!row?.is_calculable) return acc;
        const lineId = String(row?.budget_line_id ?? row?.linea_id ?? '');
        const planningNode = planningMap.get(lineId) || null;
        const totalSlack = Math.max(0, Number(planningNode?.totalSlack || 0));
        if (totalSlack > 0.0001) return acc;

        acc.criticalRows += 1;
        const draft = drafts?.[lineId] || {};
        const crashingReview = resolveGanttCrashingReview(row, draft);
        if (!crashingReview?.review_ready) return acc;

        const daysSaved = Math.max(0, Number(crashingReview.days_saved_with_next_resource || 0));
        const temporalRelease = Math.max(0, Number(crashingReview.temporal_cost_release || 0));
        const incrementalResourceCostProxy = Math.max(0, Number(crashingReview.incremental_resource_total_cost_proxy || 0));
        const netCrashingCostDeltaProxy = Number(crashingReview.net_crashing_cost_delta_proxy || 0);
        const incrementalCostPerDaySavedProxy = Number(crashingReview.incremental_cost_per_day_saved_proxy || 0);
        const equipmentOwnershipGap = Boolean(crashingReview.equipment_cost_traceability_gap);
        acc.reviewReadyRows += 1;
        acc.totalDaysSaved += daysSaved;
        acc.totalTemporalRelease += temporalRelease;
        acc.totalIncrementalResourceCostProxy += incrementalResourceCostProxy;
        acc.totalNetCrashingCostDeltaProxy += netCrashingCostDeltaProxy;
        if (equipmentOwnershipGap) {
            acc.equipmentOwnershipGapRows += 1;
        } else {
            acc.traceableRows += 1;
        }
        acc.topEntries.push({
            id: lineId,
            codigo: row?.codigo_item || lineId,
            descripcion: row?.descripcion || 'APU',
            daysSaved: roundConfigNumber(daysSaved, 4),
            temporalRelease: roundConfigNumber(temporalRelease, 4),
            incrementalResourceCostProxy: roundConfigNumber(incrementalResourceCostProxy, 4),
            netCrashingCostDeltaProxy: roundConfigNumber(netCrashingCostDeltaProxy, 4),
            incrementalCostPerDaySavedProxy: roundConfigNumber(incrementalCostPerDaySavedProxy, 4),
            currentAssumedResources: roundConfigNumber(Number(crashingReview.current_assumed_resources || 0), 4),
            nextAssumedResources: roundConfigNumber(Number(crashingReview.next_assumed_resources || 0), 4),
            dominantTimeCategory: crashingReview?.dominant_time_category || 'N/D',
            economicConfidenceLevel: crashingReview?.economic_confidence_level || 'traceable',
            equipmentOwnershipGap,
            blockedForRealCrashing: Boolean(crashingReview?.blocked_for_real_crashing),
            blockingReason: crashingReview?.blocking_reason || '',
        });
        return acc;
    }, initial);

    return {
        criticalRows: aggregated.criticalRows,
        reviewReadyRows: aggregated.reviewReadyRows,
        totalDaysSaved: roundConfigNumber(aggregated.totalDaysSaved, 4),
        totalTemporalRelease: roundConfigNumber(aggregated.totalTemporalRelease, 4),
        totalIncrementalResourceCostProxy: roundConfigNumber(aggregated.totalIncrementalResourceCostProxy, 4),
        totalNetCrashingCostDeltaProxy: roundConfigNumber(aggregated.totalNetCrashingCostDeltaProxy, 4),
        traceableRows: aggregated.traceableRows,
        equipmentOwnershipGapRows: aggregated.equipmentOwnershipGapRows,
        topEntries: aggregated.topEntries
            .sort((left, right) => {
                const leftRank = left.equipmentOwnershipGap ? 1 : 0;
                const rightRank = right.equipmentOwnershipGap ? 1 : 0;
                if (leftRank !== rightRank) {
                    return leftRank - rightRank;
                }
                return left.incrementalCostPerDaySavedProxy - right.incrementalCostPerDaySavedProxy;
            })
            .slice(0, 3),
    };
};

const getGanttDurationModelReconciliation = (row = null, draft = {}) => {
    const metadata = {
        ...(row?.metadata || {}),
        ...(draft?.metadata || {}),
    };
    const snapshot = metadata?.apu_duration_reconciliation_v1;
    return snapshot && typeof snapshot === 'object' ? snapshot : null;
};

const resolveDurationModelReconciliationFreshness = (row = null, draft = {}) => {
    const reconciliation = getGanttDurationModelReconciliation(row, draft);
    if (!reconciliation) return null;
    const currentProgressPct = Number(draft?.progress_pct ?? row?.progress_pct ?? 0);
    const adoptedProgressPct = Number(reconciliation.progress_pct ?? currentProgressPct);
    const progressDelta = roundConfigNumber(currentProgressPct - adoptedProgressPct, 4);
    const currentCrew = Number(draft?.assumed_resource_units ?? row?.recursos_asumidos ?? row?.recursos_calculados ?? 1);
    const adoptedCrew = Number(reconciliation.assumed_resource_units ?? currentCrew);
    const crewDelta = roundConfigNumber(currentCrew - adoptedCrew, 4);
    const progressChanged = Number.isFinite(progressDelta) && Math.abs(progressDelta) > 0.0001;
    const crewChanged = Number.isFinite(crewDelta) && Math.abs(crewDelta) > 0.0001;
    const isStale = progressChanged || crewChanged;
    return {
        isStale,
        currentProgressPct,
        adoptedProgressPct,
        progressDelta,
        currentCrew,
        adoptedCrew,
        crewDelta,
        progressChanged,
        crewChanged,
    };
};

const resolveDurationModelAdoptionState = (row = null, draft = {}) => {
    const durationModel = resolveGanttDurationModel(row, draft);
    if (!row?.is_calculable || !durationModel) return { eligible: false, reason: '' };
    const recommendation = durationModel.remaining_duration_recommendation
        && typeof durationModel.remaining_duration_recommendation === 'object'
        ? durationModel.remaining_duration_recommendation
        : null;
    const backendEligible = recommendation ? Boolean(recommendation.eligible) : Boolean(durationModel.remaining_duration_eligible);
    const backendReason = String(
        recommendation?.reason
        || durationModel.remaining_duration_reason
        || ''
    );
    const backendDuration = Number(
        recommendation?.recommended_duration_days
        ?? durationModel.duracion_remanente_dias
        ?? 0
    );
    const backendDeltaDays = Number(
        recommendation?.delta_days
        ?? durationModel.remaining_duration_delta_days
        ?? 0
    );
    if (Object.prototype.hasOwnProperty.call(draft || {}, 'duration')) {
        return { eligible: false, reason: 'La partida ya tiene un tanteo local de duración.' };
    }
    if (hasPersistedPendingApproval(row, draft)) {
        return { eligible: false, reason: 'La partida ya tiene una aprobación pendiente.' };
    }
    if (!backendEligible || !Number.isFinite(backendDuration) || backendDuration < 0) {
        return { eligible: false, reason: backendReason };
    }
    return {
        eligible: true,
        reason: backendReason,
        duration: roundConfigNumber(backendDuration, 4),
        deltaDays: backendDeltaDays,
    };
};

const resolveDurationModelRowSignal = (row = null, draft = {}) => {
    if (!row?.is_calculable) return null;
    const durationModel = resolveGanttDurationModel(row, draft);
    if (!durationModel) return null;
    const recommendation = durationModel.remaining_duration_recommendation
        && typeof durationModel.remaining_duration_recommendation === 'object'
        ? durationModel.remaining_duration_recommendation
        : null;
    const durationReconciliation = getGanttDurationModelReconciliation(row, draft);
    const reconciliationFreshness = resolveDurationModelReconciliationFreshness(row, draft);
    if (durationReconciliation) {
        if (reconciliationFreshness?.isStale) {
            const reasons = [];
            if (reconciliationFreshness.progressChanged) {
                reasons.push(
                    `Avance adoptado: ${formatNumber(reconciliationFreshness.adoptedProgressPct, 1)}%\nAvance actual: ${formatNumber(reconciliationFreshness.currentProgressPct, 1)}%`
                );
            }
            if (reconciliationFreshness.crewChanged) {
                reasons.push(
                    `Cuadrilla adoptada: ${formatNumber(reconciliationFreshness.adoptedCrew, 2)}\nCuadrilla actual: ${formatNumber(reconciliationFreshness.currentCrew, 2)}`
                );
            }
            return {
                tone: 'stale',
                label: 'APU',
                tooltip: `El tanteo local de duración remanente quedó desactualizado porque cambió la base operativa.\n${reasons.join('\n')}\nRevisa o vuelve a adoptar la duración remanente.`,
            };
        }
        return {
            tone: 'applied',
            label: 'APU',
            tooltip: `La tarea usa un tanteo local de duración remanente derivado del avance real.\nAdoptado: ${formatDateTime(durationReconciliation.adopted_at)}`,
        };
    }
    if (!recommendation?.eligible) return null;
    const deltaDays = Number(recommendation.delta_days ?? 0);
    if (!Number.isFinite(deltaDays) || Math.abs(deltaDays) <= 0.0001) return null;
    const recommendedDuration = Number(recommendation.recommended_duration_days ?? 0);
    const currentDuration = Number(recommendation.current_duration_days ?? 0);
    return {
        tone: 'warning',
        label: 'APU',
        tooltip: `La duración visible no coincide con el remanente técnico del APU.\nActual: ${formatNumber(currentDuration, 2)} d\nRemanente: ${formatNumber(recommendedDuration, 2)} d\nΔ duración: ${formatNumber(deltaDays, 2)} d`,
    };
};

const resolveResourcePressureState = (row = null, draft = {}) => {
    if (!row?.is_calculable) return null;
    const calculatedCrew = Number(row?.recursos_calculados ?? row?.cuadrilla_total ?? 0);
    const assumedCrew = Number(
        draft?.assumed_resource_units
        ?? row?.recursos_asumidos
        ?? row?.recursos_calculados
        ?? row?.cuadrilla_total
        ?? 0
    );
    const equiposCrew = Number(row?.cuadrilla_equipos ?? 0);
    const manoObraCrew = Number(row?.cuadrilla_mano_obra ?? 0);
    const delta = roundConfigNumber(assumedCrew - calculatedCrew, 4);
    const ratio = calculatedCrew > 0 ? roundConfigNumber(assumedCrew / calculatedCrew, 4) : null;
    const hasCalculatedCrew = calculatedCrew > 0.0001;
    const governingCrewCategory = equiposCrew >= manoObraCrew
        ? (equiposCrew > 0 ? 'Equipos y Herramientas' : 'Sin cuadrilla calculada')
        : 'Mano de Obra';
    const governingCrewUnits = Math.max(equiposCrew, manoObraCrew, 0);

    if (!hasCalculatedCrew) {
        return {
            tone: 'informational',
            label: 'Sin base',
            chipClassName: 'border-zinc-200 bg-white text-zinc-500',
            panelClassName: 'border-zinc-200 bg-zinc-50',
            panelAccentClassName: 'text-zinc-500',
            title: 'Sin cuadrilla calculada',
            tooltip: 'La partida no tiene una cuadrilla calculada operativa para comparar los recursos asumidos.',
            calculatedCrew,
            assumedCrew,
            delta,
            ratio,
            governingCrewCategory,
            governingCrewUnits,
        };
    }

    if (Math.abs(delta) <= 0.0001) {
        return {
            tone: 'balanced',
            label: 'Equilibrada',
            chipClassName: 'border-emerald-200 bg-emerald-50 text-emerald-700',
            panelClassName: 'border-emerald-200 bg-emerald-50',
            panelAccentClassName: 'text-emerald-700',
            title: 'Cuadrilla alineada',
            tooltip: `La cuadrilla asumida coincide con la cuadrilla calculada del APU.\nCalculada: ${formatNumber(calculatedCrew, 2)}\nAsumida: ${formatNumber(assumedCrew, 2)}`,
            calculatedCrew,
            assumedCrew,
            delta,
            ratio,
            governingCrewCategory,
            governingCrewUnits,
        };
    }

    if (delta > 0) {
        return {
            tone: 'reinforced',
            label: 'Refuerzo',
            chipClassName: 'border-sky-200 bg-sky-50 text-sky-700',
            panelClassName: 'border-sky-200 bg-sky-50',
            panelAccentClassName: 'text-sky-700',
            title: 'Cuadrilla reforzada',
            tooltip: `La cuadrilla asumida es mayor que la cuadrilla calculada del APU.\nCalculada: ${formatNumber(calculatedCrew, 2)}\nAsumida: ${formatNumber(assumedCrew, 2)}\nΔ: +${formatNumber(delta, 2)}`,
            calculatedCrew,
            assumedCrew,
            delta,
            ratio,
            governingCrewCategory,
            governingCrewUnits,
        };
    }

    return {
        tone: 'under',
        label: 'Por debajo',
        chipClassName: 'border-amber-200 bg-amber-50 text-amber-700',
        panelClassName: 'border-amber-200 bg-amber-50',
        panelAccentClassName: 'text-amber-700',
        title: 'Cuadrilla reducida',
        tooltip: `La cuadrilla asumida es menor que la cuadrilla calculada del APU.\nCalculada: ${formatNumber(calculatedCrew, 2)}\nAsumida: ${formatNumber(assumedCrew, 2)}\nΔ: ${formatNumber(delta, 2)}`,
        calculatedCrew,
        assumedCrew,
        delta,
        ratio,
        governingCrewCategory,
        governingCrewUnits,
    };
};

const buildClearedPendingApprovalMetadata = (row = null, draft = {}) => {
    const metadata = {
        ...(row?.metadata || {}),
        ...(draft?.metadata || {}),
    };
    delete metadata[GANTT_PENDING_APPROVAL_KEY];
    delete metadata[GANTT_RESOURCE_PENDING_APPROVAL_KEY];
    return metadata;
};

const getGanttConfirmedSnapshot = (row = null, draft = {}) => {
    const metadata = {
        ...(row?.metadata || {}),
        ...(draft?.metadata || {}),
    };
    const snapshot = metadata?.[GANTT_CONFIRMED_SNAPSHOT_KEY];
    return snapshot && typeof snapshot === 'object' ? snapshot : null;
};

const getGanttConfirmedHistory = (row = null, draft = {}) => {
    const metadata = {
        ...(row?.metadata || {}),
        ...(draft?.metadata || {}),
    };
    return Array.isArray(metadata?.[GANTT_CONFIRMED_HISTORY_KEY]) ? metadata[GANTT_CONFIRMED_HISTORY_KEY] : [];
};

const getGanttCpmTraceEvents = (row = null, draft = {}) => {
    const metadata = {
        ...(row?.metadata || {}),
        ...(draft?.metadata || {}),
    };
    return Array.isArray(metadata?.[GANTT_CPM_TRACE_KEY]) ? metadata[GANTT_CPM_TRACE_KEY] : [];
};

const appendGanttCpmTraceEvent = (row = null, draft = {}, event = {}) => {
    const metadata = {
        ...(row?.metadata || {}),
        ...(draft?.metadata || {}),
    };
    const previous = getGanttCpmTraceEvents(row, draft);
    const nextEvent = {
        occurred_at: event.occurred_at || new Date().toISOString(),
        action: String(event.action || 'unknown'),
        mode: String(event.mode || 'line'),
        source: String(event.source || 'gantt_cpm_reconciliation'),
        actor_user_id: event.actor_user_id ?? null,
        actor_email: event.actor_email || null,
        actor_role: event.actor_role || null,
        recommended_start: event.recommended_start || null,
        recommended_finish: event.recommended_finish || null,
        recommended_duration_days: Number(event.recommended_duration_days || 0),
    };
    metadata[GANTT_CPM_TRACE_KEY] = [nextEvent, ...previous].slice(0, 12);
    return metadata;
};

const hasPersistedConfirmedSnapshot = (row = null, draft = {}) => Boolean(getGanttConfirmedSnapshot(row, draft));

const snapshotsAreEquivalent = (left = null, right = null) => {
    if (!left || !right) return false;
    return (
        String(left.start_date || '') === String(right.start_date || '')
        && String(left.end_date || '') === String(right.end_date || '')
        && Number(left.duration || 0) === Number(right.duration || 0)
        && Number(left.progress_pct || 0) === Number(right.progress_pct || 0)
        && Number(left.assumed_resource_units || 0) === Number(right.assumed_resource_units || 0)
        && JSON.stringify(left.dependencies || []) === JSON.stringify(right.dependencies || [])
    );
};

const buildConfirmedSnapshotMetadata = (row, draft = {}, config = {}, context = {}) => {
    const metadata = buildClearedPendingApprovalMetadata(row, draft);
    const cpmReconciliation = getGanttCpmManualReconciliation(row, draft);
    const cpmTraceEvents = getGanttCpmTraceEvents(row, draft);
    const latestCpmTrace = cpmTraceEvents[0] || null;
    const snapshot = {
        ...buildGanttBaselineSnapshot(row, draft, config),
        confirmed_at: context.confirmedAt || new Date().toISOString(),
        source: context.source || 'gantt_approval',
        cpm_reconciled: Boolean(cpmReconciliation),
        cpm_mode: latestCpmTrace?.mode || null,
        cpm_last_action: latestCpmTrace?.action || null,
        cpm_last_actor_email: latestCpmTrace?.actor_email || null,
    };
    metadata[GANTT_CONFIRMED_SNAPSHOT_KEY] = snapshot;
    const previousHistory = getGanttConfirmedHistory(row, draft);
    const nextHistory = snapshotsAreEquivalent(previousHistory[0], snapshot)
        ? previousHistory
        : [snapshot, ...previousHistory].slice(0, 8);
    metadata[GANTT_CONFIRMED_HISTORY_KEY] = nextHistory;
    return metadata;
};

const buildDraftFromConfirmedSnapshot = (row = null, draft = {}, config = {}) => {
    const snapshot = getGanttConfirmedSnapshot(row, draft);
    if (!snapshot) return null;
    const startDate = shiftToGanttWorkingDateTime(snapshot.start_date, config, 1);
    return {
        start_date: toNativeDateTimeValue(startDate, config, 'start'),
        duration: Number(snapshot.duration ?? row?.dias_calendario ?? row?.dias_utiles ?? 0),
        end_date: snapshot.end_date || null,
        progress_pct: Number(snapshot.progress_pct ?? row?.progress_pct ?? 0),
        assumed_resource_units: Number(snapshot.assumed_resource_units ?? row?.recursos_asumidos ?? row?.recursos_calculados ?? 1),
        predecessors: Array.isArray(snapshot.predecessors) ? snapshot.predecessors.join(', ') : '',
        dependencies: Array.isArray(snapshot.dependencies) ? snapshot.dependencies : [],
        metadata: buildClearedPendingApprovalMetadata(row, draft),
    };
};

const resolveGanttGovernanceState = (row = null, draft = {}) => {
    const keys = Object.keys(draft || {});
    const pendingApproval = getGanttPendingApprovalState(row, draft);
    const pendingSource = String(pendingApproval?.source || '');
    const pendingReason = String(pendingApproval?.reason || '');
    if (!keys.length) {
        if (pendingApproval?.reason === 'resource') {
            return {
                id: 'pending-apu-persisted',
                label: 'Pendiente APU',
                className: 'border-[#F39200]/25 bg-[#fff7ed] text-[#F39200]',
                tooltip: 'La línea ya tiene un borrador operativo guardado desde el editor de recursos/rendimientos. Sigue pendiente de aprobación final.',
            };
        }
        if (pendingApproval) {
            return {
                id: 'pending-approval',
                label: 'Pendiente aprobar',
                className: 'border-amber-200 bg-amber-50 text-amber-700',
                tooltip: 'La línea tiene cambios de cronograma persistidos como borrador y sigue pendiente de aprobación explícita.',
            };
        }
        if (hasPersistedConfirmedSnapshot(row, draft)) {
            return {
                id: 'confirmed',
                label: 'Confirmado',
                className: 'border-emerald-200 bg-emerald-50 text-emerald-700',
                tooltip: 'La línea coincide con el último snapshot confirmado del cronograma.',
            };
        }
        return {
            id: 'synced',
            label: 'Sincronizado',
            className: 'border-emerald-200 bg-emerald-50 text-emerald-700',
            tooltip: 'La fila no tiene cambios locales pendientes y sigue sincronizada con el cronograma confirmado.',
        };
    }

    if (keys.some((key) => GANTT_RESOURCE_DRAFT_KEYS.has(key))) {
        return {
            id: 'pending-apu',
            label: 'Pendiente APU',
            className: 'border-[#F39200]/25 bg-[#fff7ed] text-[#F39200]',
            tooltip: 'Hay cambios que afectan la duración o los recursos asumidos. La conciliación debe hacerse desde el editor de recursos/rendimientos del APU operativo.',
        };
    }

    if (
        pendingReason === 'schedule'
        && pendingSource === 'gantt_conflict_relief'
        && keys.some((key) => GANTT_SCHEDULE_DRAFT_KEYS.has(key))
    ) {
        return {
            id: 'conflict-relief-draft',
            label: 'Alivio RR',
            className: 'border-sky-200 bg-sky-50 text-sky-700',
            tooltip: 'La fila adoptó un tanteo local de alivio de conflicto de recursos. Sigue pendiente de revisión o aprobación.',
        };
    }

    if (keys.some((key) => GANTT_SCHEDULE_DRAFT_KEYS.has(key))) {
        return {
            id: 'schedule-draft',
            label: 'Programación ajustada',
            className: 'border-sky-200 bg-sky-50 text-sky-700',
            tooltip: 'La fila tiene cambios de programación en borrador: fechas, secuencia o dependencias. No afectan todavía al presupuesto.',
        };
    }

    return {
        id: 'draft',
        label: 'En tanteo',
        className: 'border-zinc-200 bg-zinc-100 text-zinc-600',
        tooltip: 'La fila tiene cambios locales pendientes de revisar o confirmar.',
    };
};

const buildComparableConfirmedRow = (row = null, draft = {}, config = {}) => {
    const snapshot = getGanttConfirmedSnapshot(row, draft);
    if (!row || !snapshot) return null;
    const startDate = shiftToGanttLaborableDate(snapshot.start_date, config, 1);
    const duration = Number(snapshot.duration ?? row?.dias_calendario ?? row?.dias_utiles ?? 0);
    const endDate = duration <= 0 ? startDate : addInclusiveGanttDuration(startDate, duration, config);
    return {
        ...row,
        start_date: startDate,
        end_date: endDate,
        dias_calendario: duration,
        dias_utiles: duration,
        progress_pct: Number(snapshot.progress_pct ?? row?.progress_pct ?? 0),
        recursos_asumidos: Number(snapshot.assumed_resource_units ?? row?.recursos_asumidos ?? row?.recursos_calculados ?? 1),
        predecessors: Array.isArray(snapshot.predecessors) ? snapshot.predecessors : [],
        dependencies: Array.isArray(snapshot.dependencies) ? snapshot.dependencies : [],
        metadata: {
            ...(row?.metadata || {}),
            [GANTT_CONFIRMED_SNAPSHOT_KEY]: snapshot,
        },
    };
};

const buildComparableBudgetRowMap = (trabajo = null) => {
    const rows = Array.isArray(trabajo?.rows) ? trabajo.rows : [];
    return new Map(
        rows
            .filter((row) => row?.is_calculable)
            .map((row) => [String(row.budget_line_id ?? row.linea_id), row]),
    );
};

const buildGanttDiffEntry = (row, draft = {}, compareRow = null, config = {}) => {
    if (!row?.is_calculable) return null;
    const currentEffective = applyGanttRowDraft(row, draft, config);
    const currentDependencies = normalizeRowDependencies(row, draft);
    const compareEffective = compareRow ? applyGanttRowDraft(compareRow, {}, config) : null;
    const compareDependencies = compareRow ? normalizeRowDependencies(compareRow, {}) : [];
    const currentStart = shiftToGanttLaborableDate(currentEffective.start_date, config, 1);
    const currentFinish = resolveGanttRowFinishDate(currentEffective, {}, config);
    const compareStart = compareEffective ? shiftToGanttLaborableDate(compareEffective.start_date, config, 1) : null;
    const compareFinish = compareEffective ? resolveGanttRowFinishDate(compareEffective, {}, config) : null;
    const currentDuration = Number(getGanttRowDuration(row, draft) || 0);
    const compareDuration = compareEffective
        ? Number(compareEffective.dias_calendario ?? compareEffective.dias_utiles ?? 0)
        : 0;
    const currentCrew = Number(currentEffective.recursos_asumidos ?? currentEffective.recursos_calculados ?? 1);
    const compareCrew = compareEffective
        ? Number(compareEffective.recursos_asumidos ?? compareEffective.recursos_calculados ?? 1)
        : 0;
    const startDelta = compareStart ? countGanttWorkDaysBetween(compareStart, currentStart, config) : currentDuration;
    const finishDelta = compareFinish ? countGanttWorkDaysBetween(compareFinish, currentFinish, config) : currentDuration;
    const durationDelta = currentDuration - compareDuration;
    const crewDelta = currentCrew - compareCrew;
    const currentQuantity = Number(currentEffective.cantidad ?? row?.cantidad ?? 0);
    const compareQuantity = compareEffective ? Number(compareEffective.cantidad ?? compareRow?.cantidad ?? 0) : 0;
    const quantityDelta = currentQuantity - compareQuantity;
    const currentWorkHours = Number(currentEffective.horas_total ?? row?.horas_total ?? currentEffective.trabajo_total ?? row?.trabajo_total ?? 0);
    const compareWorkHours = compareEffective
        ? Number(compareEffective.horas_total ?? compareRow?.horas_total ?? compareEffective.trabajo_total ?? compareRow?.trabajo_total ?? 0)
        : 0;
    const workHoursDelta = currentWorkHours - compareWorkHours;
    const categoryDiffs = compareEffective
        ? [
            {
                key: 'equipos',
                label: 'Equipos',
                delta: Number(currentEffective.horas_equipos ?? row?.horas_equipos ?? 0) - Number(compareEffective.horas_equipos ?? compareRow?.horas_equipos ?? 0),
            },
            {
                key: 'mano_obra',
                label: 'Mano de obra',
                delta: Number(currentEffective.horas_mano_obra ?? row?.horas_mano_obra ?? 0) - Number(compareEffective.horas_mano_obra ?? compareRow?.horas_mano_obra ?? 0),
            },
            {
                key: 'transporte',
                label: 'Transporte',
                delta: Number(currentEffective.horas_transporte ?? row?.horas_transporte ?? 0) - Number(compareEffective.horas_transporte ?? compareRow?.horas_transporte ?? 0),
            },
        ]
        : [];
    const dominantCategory = [...categoryDiffs].sort((left, right) => Math.abs(right.delta) - Math.abs(left.delta))[0] || null;
    const dependencyChanged = JSON.stringify(currentDependencies) !== JSON.stringify(compareDependencies);
    const changed = !compareEffective
        || Math.abs(startDelta) > 0.0001
        || Math.abs(finishDelta) > 0.0001
        || Math.abs(durationDelta) > 0.0001
        || Math.abs(crewDelta) > 0.0001
        || Math.abs(quantityDelta) > 0.0001
        || Math.abs(workHoursDelta) > 0.0001
        || dependencyChanged;
    if (!changed) return null;
    return {
        id: String(row.budget_line_id ?? row.linea_id),
        codigo: row.codigo_item || String(row.budget_line_id ?? row.linea_id),
                        descripcion: formatCronogramaDescripcion(row) || 'Partida sin descripción',
        startDelta,
        finishDelta,
        durationDelta,
        crewDelta,
        quantityDelta,
        workHoursDelta,
        dependencyChanged,
        isNew: !compareEffective,
        dominantCategory,
        impactScore: Math.abs(durationDelta) + Math.abs(crewDelta) + Math.abs(quantityDelta) + Math.abs(workHoursDelta / 8) + (dependencyChanged ? 1 : 0),
        current: {
            start: currentStart,
            finish: currentFinish,
            duration: currentDuration,
            crew: currentCrew,
            quantity: currentQuantity,
            workHours: currentWorkHours,
            dependencies: currentDependencies,
        },
        compare: compareEffective
            ? {
                start: compareStart,
                finish: compareFinish,
                duration: compareDuration,
                crew: compareCrew,
                quantity: compareQuantity,
                workHours: compareWorkHours,
                dependencies: compareDependencies,
            }
            : null,
    };
};

const summarizeGanttDiffEntries = (entries = []) => {
    const normalized = Array.isArray(entries) ? entries : [];
    return {
        changedRows: normalized.length,
        newRows: normalized.filter((entry) => entry.isNew).length,
        durationRows: normalized.filter((entry) => Math.abs(entry.durationDelta) > 0.0001).length,
        crewRows: normalized.filter((entry) => Math.abs(entry.crewDelta) > 0.0001).length,
        quantityRows: normalized.filter((entry) => Math.abs(entry.quantityDelta) > 0.0001).length,
        workRows: normalized.filter((entry) => Math.abs(entry.workHoursDelta) > 0.0001).length,
        dependencyRows: normalized.filter((entry) => entry.dependencyChanged).length,
        totalDurationDelta: normalized.reduce((acc, entry) => acc + Math.abs(entry.durationDelta), 0),
        totalCrewDelta: normalized.reduce((acc, entry) => acc + Math.abs(entry.crewDelta), 0),
        totalQuantityDelta: normalized.reduce((acc, entry) => acc + Math.abs(entry.quantityDelta), 0),
        totalWorkHoursDelta: normalized.reduce((acc, entry) => acc + Math.abs(entry.workHoursDelta), 0),
        topEntries: [...normalized]
            .sort((left, right) => right.impactScore - left.impactScore)
            .slice(0, 4),
    };
};

const buildGanttBaselineSnapshot = (row, draft = {}, config = {}) => {
    const effectiveRow = applyGanttRowDraft(row, draft, config);
    const startDate = shiftToGanttWorkingDateTime(effectiveRow.start_date, config, 1);
    const duration = getGanttRowDuration(row, draft);
    const endDate = resolveGanttRowFinishDate(row, { ...draft, start_date: startDate, duration }, config);
    return {
        captured_at: new Date().toISOString(),
        start_date: toNativeDateTimeValue(startDate, config, 'start'),
        end_date: toNativeDateTimeValue(endDate, config, 'finish'),
        duration: Number(duration || 0),
        progress_pct: Number(effectiveRow.progress_pct || 0),
        assumed_resource_units: Number(effectiveRow.recursos_asumidos || 0),
    };
};

const getGanttUnconstrainedScheduleSnapshot = (row = null, draft = {}) => {
    const metadata = {
        ...(row?.metadata || {}),
        ...(draft?.metadata || {}),
    };
    const snapshot = metadata?.[GANTT_UNCONSTRAINED_SCHEDULE_KEY];
    return snapshot && typeof snapshot === 'object' ? snapshot : null;
};

const buildGanttUnconstrainedScheduleSnapshot = (row, draft = {}, config = {}) => {
    const normalizedDraft = { ...(draft || {}) };
    delete normalizedDraft.predecessors;
    delete normalizedDraft.dependencies;

    // Cuando la tarea todavía no estaba gobernada por relaciones, el inicio original
    // es el de la fila persistida; si ya estaba gobernada, preservamos el snapshot previo.
    if (normalizeRowDependencies(row, {}).length === 0) {
        delete normalizedDraft.start_date;
        delete normalizedDraft.end_date;
    }

    const effectiveRow = applyGanttRowDraft(row, normalizedDraft, config);
    const startDate = shiftToGanttWorkingDateTime(
        normalizedDraft.start_date || row?.start_date,
        config,
        1,
    );
    const duration = getGanttRowDuration(row, normalizedDraft);
    const endDate = resolveGanttRowFinishDate(
        row,
        {
            ...normalizedDraft,
            start_date: startDate,
            duration,
        },
        config,
    );
    return {
        captured_at: new Date().toISOString(),
        start_date: toNativeDateTimeValue(startDate, config, 'start'),
        end_date: toNativeDateTimeValue(endDate, config, 'finish'),
        duration: Number(duration || 0),
        progress_pct: Number(effectiveRow?.progress_pct || 0),
        assumed_resource_units: Number(effectiveRow?.recursos_asumidos || 0),
    };
};

const resolveDependencyPersistenceContract = (row, draft = {}, metadata = {}, config = {}) => {
    const dependencies = normalizeRowDependencies(row, draft);
    const existingSnapshot = getGanttUnconstrainedScheduleSnapshot(row, draft);
    const confirmedSnapshot = getGanttConfirmedSnapshot(row, draft);
    const nextMetadata = { ...(metadata || {}) };

    if (dependencies.length > 0) {
        nextMetadata[GANTT_UNCONSTRAINED_SCHEDULE_KEY] = existingSnapshot
            || buildGanttUnconstrainedScheduleSnapshot(row, draft, config);
        return {
            metadata: nextMetadata,
            restoredSnapshot: null,
        };
    }

    const restorationSnapshot = existingSnapshot || confirmedSnapshot;
    if (restorationSnapshot) {
        delete nextMetadata[GANTT_UNCONSTRAINED_SCHEDULE_KEY];
        return {
            metadata: nextMetadata,
            restoredSnapshot: restorationSnapshot,
        };
    }

    return {
        metadata: nextMetadata,
        restoredSnapshot: null,
    };
};

const getSegmentSnapVisual = (currentXPx, segmentWidth, segmentCount) => {
    if (!Number.isFinite(currentXPx) || !Number.isFinite(segmentWidth) || segmentWidth <= 0 || segmentCount <= 0) {
        return null;
    }
    const maxIndex = Math.max(segmentCount - 1, 0);
    const columnIndex = clamp(Math.floor(currentXPx / segmentWidth), 0, maxIndex);
    const boundaryIndex = clamp(Math.round(currentXPx / segmentWidth), 0, segmentCount);
    return {
        shadeLeft: columnIndex * segmentWidth,
        shadeWidth: segmentWidth,
        guideLeft: boundaryIndex * segmentWidth,
    };
};

const resolveRowLineId = (row) => String(row?.budget_line_id ?? row?.linea_id ?? '');

const buildManualMilestoneLineId = (milestoneId) => `manual-milestone:${String(milestoneId || '').trim()}`;
const MANUAL_MILESTONE_START_SENTINEL = '__START__';

const resolveManualMilestonePersistenceAnchorLineId = (rows = [], requestedAnchorId = '', calculableLineIds = null) => {
    const normalizedRequestedAnchorId = String(requestedAnchorId || '').trim();
    if (normalizedRequestedAnchorId === MANUAL_MILESTONE_START_SENTINEL) {
        return '';
    }
    const orderedRows = Array.isArray(rows) ? rows : [];
    const validCalculableIds = calculableLineIds instanceof Set ? calculableLineIds : null;
    const isPersistableCalculable = (row) => {
        const lineId = resolveRowLineId(row);
        if (!lineId) return false;
        if (validCalculableIds) {
            return validCalculableIds.has(lineId);
        }
        return Boolean(row?.is_calculable);
    };
    if (!orderedRows.length) return normalizedRequestedAnchorId;
    const requestedIndex = normalizedRequestedAnchorId
        ? orderedRows.findIndex((candidate) => resolveRowLineId(candidate) === normalizedRequestedAnchorId)
        : -1;
    if (requestedIndex >= 0) {
        const requestedRow = orderedRows[requestedIndex];
        if (isPersistableCalculable(requestedRow)) {
            return resolveRowLineId(requestedRow);
        }
        for (let index = requestedIndex + 1; index < orderedRows.length; index += 1) {
            if (isPersistableCalculable(orderedRows[index])) {
                return resolveRowLineId(orderedRows[index]);
            }
        }
        for (let index = requestedIndex - 1; index >= 0; index -= 1) {
            if (isPersistableCalculable(orderedRows[index])) {
                return resolveRowLineId(orderedRows[index]);
            }
        }
    }
    const firstCalculable = orderedRows.find((candidate) => isPersistableCalculable(candidate));
    return firstCalculable ? resolveRowLineId(firstCalculable) : normalizedRequestedAnchorId;
};

const buildSyntheticManualMilestoneRow = (milestone = {}, anchorRow = null, fallbackProjectStart = null) => {
    const milestoneId = String(milestone?.id || '').trim();
    if (!milestoneId) return null;
    const lineId = buildManualMilestoneLineId(milestoneId);
    const milestoneStart = milestone?.start_date
        || anchorRow?.start_date
        || fallbackProjectStart
        || null;
    const anchorLevel = Number(anchorRow?.level || 0);
    return {
        linea_id: lineId,
        budget_line_id: lineId,
        presupuesto_linea_id: lineId,
        sequence_index: Number(anchorRow?.sequence_index || 0),
        edt_id: anchorRow?.edt_id ?? null,
        apu_id: null,
        codigo_item: '',
        descripcion: String(milestone?.descripcion || 'Nuevo hito').trim() || 'Nuevo hito',
        unidad: null,
        cantidad: 0,
        tipo: 'manual_milestone',
        calculation_mode: 'manual_milestone',
        nested_apu_count: 0,
        native_line_count: 0,
        nested_line_count: 0,
        rendimiento_unitario_equipos: 0,
        rendimiento_unitario_mano_obra: 0,
        rendimiento_unitario_transporte: 0,
        trabajo_equipos: 0,
        trabajo_mano_obra: 0,
        trabajo_transporte: 0,
        trabajo_gobernante: 0,
        recurso_gobernante_id: null,
        recurso_gobernante_nombre: null,
        recurso_gobernante_categoria_detalle: null,
        recurso_gobernante_criterio: null,
        recurso_gobernante_costo_hora: 0,
        trabajo_total: 0,
        trabajo_propio: 0,
        trabajo_hijos: 0,
        cuadrilla_equipos: 0,
        cuadrilla_mano_obra: 0,
        cuadrilla_total: 0,
        cuadrilla_propia: 0,
        cuadrilla_hijos: 0,
        horas_equipos: 0,
        horas_mano_obra: 0,
        horas_transporte: 0,
        horas_total: 0,
        recursos_calculados: 0,
        recursos_asumidos: 0,
        duracion_horas: 0,
        dias_utiles: 0,
        dias_calendario: 0,
        duracion_horas_exportacion: 0,
        dias_utiles_exportacion: 0,
        dias_calendario_exportacion: 0,
        start_date: milestoneStart,
        end_date: milestoneStart,
        predecessors: Array.isArray(milestone?.predecessors)
            ? milestone.predecessors.map(normalizeDependencyEndpointId).filter(Boolean)
            : [],
        dependencies: Array.isArray(milestone?.dependencies)
            ? buildNormalizedDependencies(lineId, milestone.dependencies)
            : [],
        progress_pct: 0,
        categorias: {},
        level: anchorLevel,
        is_calculable: false,
        metadata: {
            is_milestone: true,
            milestone: true,
            manual_milestone: true,
            manual_milestone_id: milestoneId,
            after_line_id: String(milestone?.after_line_id || '').trim(),
            display_after_line_id: String(
                milestone?.display_after_line_id === MANUAL_MILESTONE_START_SENTINEL
                    ? MANUAL_MILESTONE_START_SENTINEL
                    : (milestone?.display_after_line_id || milestone?.after_line_id || '')
            ).trim(),
        },
    };
};

const resolveVisibleBarQuickActionsLayout = ({
    barLeftPx = 0,
    barWidthPx = 0,
    viewportScrollLeft = 0,
    viewportWidthPx = 0,
    buttonSizePx = 18,
    outsideGapPx = 6,
} = {}) => {
    const safeBarWidth = Math.max(buttonSizePx, Number(barWidthPx || 0));
    const safeViewportWidth = Math.max(1, Number(viewportWidthPx || 0));
    const gapPx = Math.max(0, Number(outsideGapPx || 0));
    const availableOutsideLeftPx = Math.max(0, Number(barLeftPx || 0) - Number(viewportScrollLeft || 0));
    const availableOutsideRightPx = Math.max(
        0,
        (Number(viewportScrollLeft || 0) + safeViewportWidth) - (Number(barLeftPx || 0) + safeBarWidth),
    );
    const isAlignedToViewportLeft = availableOutsideLeftPx <= 2;

    if (!isAlignedToViewportLeft && availableOutsideLeftPx >= (buttonSizePx + gapPx)) {
        return {
            offsetPx: -(buttonSizePx + gapPx),
            placement: 'outside-left',
        };
    }

    if (availableOutsideRightPx >= (buttonSizePx + gapPx)) {
        return {
            offsetPx: safeBarWidth + gapPx,
            placement: 'outside-right',
        };
    }

    if (availableOutsideLeftPx >= (buttonSizePx + gapPx)) {
        return {
            offsetPx: -(buttonSizePx + gapPx),
            placement: 'outside-left',
        };
    }

    return {
        offsetPx: Math.max(0, safeBarWidth - buttonSizePx),
        placement: 'inside',
    };
};

const mergeManualMilestonesIntoRows = (rows = [], manualMilestones = [], fallbackProjectStart = null) => {
    const orderedRows = Array.isArray(rows) ? [...rows] : [];
    const normalizedMilestones = Array.isArray(manualMilestones) ? manualMilestones.filter(Boolean) : [];
    if (!normalizedMilestones.length) return orderedRows;

    const resolveMilestoneAnchorId = (milestone) => String(
        milestone?.display_after_line_id === MANUAL_MILESTONE_START_SENTINEL
            ? MANUAL_MILESTONE_START_SENTINEL
            : (milestone?.display_after_line_id || milestone?.after_line_id || '')
    ).trim();
    const resolveManualMilestoneInsertIndex = (anchorIndex, anchorId, insertAtStart = false) => {
        let insertIndex = insertAtStart ? 0 : anchorIndex + 1;
        while (insertIndex < orderedRows.length) {
            const candidate = orderedRows[insertIndex];
            if (!isManualMilestoneRow(candidate)) break;
            const candidateAnchorId = String(candidate?.metadata?.display_after_line_id || '').trim();
            if (candidateAnchorId !== anchorId) break;
            insertIndex += 1;
        }
        return insertIndex;
    };

    const pendingMilestones = [...normalizedMilestones];
    let guard = 0;
    while (pendingMilestones.length && guard < normalizedMilestones.length + 2) {
        let insertedInPass = false;
        for (let index = 0; index < pendingMilestones.length;) {
            const milestone = pendingMilestones[index];
            const anchorId = resolveMilestoneAnchorId(milestone);
            const insertAtStart = anchorId === MANUAL_MILESTONE_START_SENTINEL;
            const anchorIndex = insertAtStart
                ? -1
                : (anchorId
                    ? orderedRows.findIndex((candidate) => resolveRowLineId(candidate) === anchorId)
                    : -1);

            if (anchorId && !insertAtStart && anchorIndex < 0) {
                index += 1;
                continue;
            }

            const anchorRow = insertAtStart
                ? (orderedRows[0] || null)
                : (anchorIndex >= 0 ? orderedRows[anchorIndex] : orderedRows[orderedRows.length - 1] || null);
            const syntheticRow = buildSyntheticManualMilestoneRow(milestone, anchorRow, fallbackProjectStart);
            if (!syntheticRow) {
                pendingMilestones.splice(index, 1);
                insertedInPass = true;
                continue;
            }
            const insertIndex = insertAtStart
                ? resolveManualMilestoneInsertIndex(-1, MANUAL_MILESTONE_START_SENTINEL, true)
                : (anchorIndex >= 0
                    ? resolveManualMilestoneInsertIndex(anchorIndex, anchorId, false)
                    : orderedRows.length);
            orderedRows.splice(insertIndex, 0, syntheticRow);
            pendingMilestones.splice(index, 1);
            insertedInPass = true;
        }

        if (!insertedInPass) break;
        guard += 1;
    }

    pendingMilestones.forEach((milestone) => {
        const anchorId = resolveMilestoneAnchorId(milestone);
        const anchorRow = orderedRows[orderedRows.length - 1] || null;
        const syntheticRow = buildSyntheticManualMilestoneRow(milestone, anchorRow, fallbackProjectStart);
        if (syntheticRow) {
            orderedRows.push(syntheticRow);
        }
        if (anchorId) {
            globalThis.reportClientError?.(`No se pudo resolver el ancla visual del hito manual "${milestone?.id || ''}": ${anchorId}`);
        }
    });

    normalizedMilestones.forEach((milestone) => {
        const milestoneId = String(milestone?.id || '').trim();
        if (!milestoneId || !Array.isArray(milestone?.successor_dependencies)) return;
        const sourceLineId = buildManualMilestoneLineId(milestoneId);
        milestone.successor_dependencies.forEach((dependency) => {
            const targetLineId = normalizeDependencyEndpointId(dependency?.target_id ?? dependency?.targetId);
            if (!targetLineId || targetLineId === sourceLineId) return;
            const targetIndex = orderedRows.findIndex((candidate) => resolveRowLineId(candidate) === targetLineId);
            if (targetIndex < 0) return;
            const targetRow = orderedRows[targetIndex];
            const existingDependencies = Array.isArray(targetRow?.dependencies) ? targetRow.dependencies : [];
            const nextDependency = buildNormalizedDependencies(targetLineId, [{
                ...dependency,
                source_id: sourceLineId,
                target_id: targetLineId,
            }])[0];
            if (!nextDependency) return;
            const hasSameSource = existingDependencies.some((entry) => (
                String(entry?.source_id ?? entry?.sourceId ?? entry?.predecessor_id ?? '') === sourceLineId
            ));
            if (hasSameSource) return;
            orderedRows[targetIndex] = {
                ...targetRow,
                dependencies: [...existingDependencies, nextDependency],
            };
        });
    });

    return orderedRows;
};

const buildTaskSerialMaps = (rows = []) => {
    const itemByLineId = new Map();
    const lineIdByItem = new Map();
    let serial = 1;
    (rows || []).forEach((row) => {
        const lineId = resolveRowLineId(row);
        if (!lineId) return;
        const item = String(serial);
        itemByLineId.set(lineId, item);
        if (row?.is_calculable || isManualMilestoneRow(row)) {
            lineIdByItem.set(item, lineId);
        }
        serial += 1;
    });
    return { itemByLineId, lineIdByItem };
};

const getRowBranchKey = (row) => {
    const code = String(row?.codigo_item || '').trim();
    if (!code) return '';
    const segments = code.split('.').filter(Boolean);
    if (segments.length <= 1) return code;
    return segments.slice(0, -1).join('.');
};

const buildGroupedRowHighlightModel = (rows = [], drafts = {}, selectedRowId = null) => {
    if (!selectedRowId) {
        return {
            relatedIds: new Set(),
            predecessorIds: new Set(),
            successorIds: new Set(),
        };
    }
    const normalizedSelectedId = String(selectedRowId);
    const rowMap = new Map(rows.map((row) => [resolveRowLineId(row), row]));
    const selectedRow = rowMap.get(normalizedSelectedId);
    if (!selectedRow) {
        return {
            relatedIds: new Set([normalizedSelectedId]),
            predecessorIds: new Set(),
            successorIds: new Set(),
        };
    }

    const relatedIds = new Set([normalizedSelectedId]);
    const predecessorIds = new Set();
    const successorIds = new Set();
    const selectedBranchKey = getRowBranchKey(selectedRow);

    if (selectedRow?.is_calculable) {
        const incomingMap = new Map();
        const outgoingMap = new Map();

        rows.forEach((row) => {
            if (!row?.is_calculable) return;
            const targetId = resolveRowLineId(row);
            const rowDraft = drafts[targetId] || {};
            getRowPredecessorIds(row, rowDraft).forEach((predecessorId) => {
                const sourceId = String(predecessorId);
                incomingMap.set(targetId, [...(incomingMap.get(targetId) || []), sourceId]);
                outgoingMap.set(sourceId, [...(outgoingMap.get(sourceId) || []), targetId]);
            });
        });

        const directPredecessors = incomingMap.get(normalizedSelectedId) || [];
        const directSuccessors = outgoingMap.get(normalizedSelectedId) || [];

        directPredecessors.forEach((rowId) => {
            if (rowMap.has(rowId)) {
                predecessorIds.add(rowId);
                relatedIds.add(rowId);
            }
        });
        directSuccessors.forEach((rowId) => {
            if (rowMap.has(rowId)) {
                successorIds.add(rowId);
                relatedIds.add(rowId);
            }
        });

        const queue = [...directPredecessors, ...directSuccessors];
        while (queue.length) {
            const currentId = String(queue.shift());
            const currentRow = rowMap.get(currentId);
            if (!currentRow?.is_calculable) continue;
            if (selectedBranchKey && getRowBranchKey(currentRow) !== selectedBranchKey) continue;

            const nextIncoming = incomingMap.get(currentId) || [];
            const nextOutgoing = outgoingMap.get(currentId) || [];
            [...nextIncoming, ...nextOutgoing].forEach((candidateId) => {
                const normalizedCandidateId = String(candidateId);
                const candidateRow = rowMap.get(normalizedCandidateId);
                if (!candidateRow?.is_calculable) return;
                if (selectedBranchKey && getRowBranchKey(candidateRow) !== selectedBranchKey) return;
                if (!relatedIds.has(normalizedCandidateId)) {
                    relatedIds.add(normalizedCandidateId);
                    queue.push(normalizedCandidateId);
                }
            });
        }
    }

    const selectedParentId = selectedRow.parent_id != null ? String(selectedRow.parent_id) : null;
    if (selectedParentId) {
        rows.forEach((row) => {
            if (row?.parent_id != null && String(row.parent_id) === selectedParentId) {
                relatedIds.add(resolveRowLineId(row));
            }
        });
    } else if (relatedIds.size <= 1) {
        const stack = [normalizedSelectedId];
        while (stack.length) {
            const currentId = stack.pop();
            rows.forEach((row) => {
                if (row?.parent_id != null && String(row.parent_id) === String(currentId)) {
                    const childId = resolveRowLineId(row);
                    if (!relatedIds.has(childId)) {
                        relatedIds.add(childId);
                        stack.push(childId);
                    }
                }
            });
        }
    }

    return {
        relatedIds,
        predecessorIds,
        successorIds,
    };
};

const getTimelineMetrics = (timelineSegments) => {
    if (!timelineSegments.length) return null;
    const timelineStart = timelineSegments[0].start;
    const timelineEnd = timelineSegments[timelineSegments.length - 1].end;
    const totalDays = Math.max(1, Math.round((timelineEnd - timelineStart) / DAY_MS) + 1);
    return {
        timelineStart,
        timelineEnd,
        totalDays,
    };
};

const shiftDateByDays = (value, days, config = {}) => {
    const parsed = normalizeDate(value);
    if (!parsed) return null;
    return addGanttWorkDays(parsed, days, config);
};

const extractInvalidCalculableLineIdFromError = (error) => {
    const detail = String(error?.response?.data?.detail || error?.message || '').trim();
    const match = detail.match(/La línea\s+(\d+)\s+no pertenece a una partida calculable/i);
    return match ? String(match[1]) : '';
};

const resolveMinimumAllowedMoveDayDelta = (interaction = null, config = {}, timelineSegments = []) => {
    const originalStart = normalizeDate(interaction?.originalStartDate);
    if (!originalStart) return null;
    const projectStart = shiftToGanttLaborableDate(
        config?.fecha_inicio_proyecto || timelineSegments?.[0]?.start,
        config,
        1,
    ) || shiftToGanttLaborableDate(timelineSegments?.[0]?.start, config, 1);
    const explicitStart = normalizeDate(interaction?.minimumAllowedStartDate);
    const constrainedStart = [projectStart, explicitStart]
        .filter(Boolean)
        .reduce((latest, item) => (item > latest ? item : latest), projectStart || explicitStart || null);
    if (!constrainedStart) return null;
    return countGanttWorkDaysBetween(originalStart, constrainedStart, config);
};

const resolveMaximumAllowedMoveDayDelta = (interaction = null, config = {}) => {
    const originalStart = normalizeDate(interaction?.originalStartDate);
    const constrainedStart = normalizeDate(interaction?.maximumAllowedStartDate);
    if (!originalStart || !constrainedStart) return null;
    return countGanttWorkDaysBetween(originalStart, constrainedStart, config);
};

const buildDependencyPath = (startPoint, endPoint, options = {}) => {
    const routeOptions = typeof options === 'boolean' ? { detour: options } : options;
    const startX = startPoint.x;
    const startY = startPoint.y;
    const endX = endPoint.x;
    const endY = endPoint.y;
    const laneOffset = startY <= endY ? -DEPENDENCY_CONNECTOR_LANE_PX : DEPENDENCY_CONNECTOR_LANE_PX;

    if (routeOptions.detour) {
        const laneX = Math.max(startX + DEPENDENCY_CONNECTOR_LANE_PX, endX + DEPENDENCY_CONNECTOR_LANE_PX);
        const laneY = Number.isFinite(routeOptions.laneY) ? routeOptions.laneY : endY + laneOffset;
        return [
            `M ${startX} ${startY}`,
            `L ${laneX} ${startY}`,
            `L ${laneX} ${laneY}`,
            `L ${endX} ${laneY}`,
            `L ${endX} ${endY}`,
        ].join(' ');
    }

    const middleX = Math.max(startX + DEPENDENCY_CONNECTOR_LANE_PX, ((startX + endX) / 2));

    return [
        `M ${startX} ${startY}`,
        `L ${middleX} ${startY}`,
        `L ${middleX} ${endY}`,
        `L ${endX} ${endY}`,
    ].join(' ');
};

const getBarVisualGeometry = (row, timelineSegments, segmentColumnWidth, config = {}) => {
    const bar = buildBarGeometry(row, timelineSegments, segmentColumnWidth, config);
    if (!bar) return null;
    const isMilestoneGeometry = Boolean(
        row?.is_milestone
        || row?.milestone
        || isManualMilestoneRow(row)
    );
    const widthPx = isMilestoneGeometry ? 18 : Math.max(1, bar.widthPx);
    const centerPx = isMilestoneGeometry ? Number(bar.leftPx || 0) : Number(bar.leftPx || 0) + (widthPx / 2);
    const leftPx = isMilestoneGeometry ? centerPx - (widthPx / 2) : Number(bar.leftPx || 0);
    const topPx = 0;
    const bottomPx = GANTT_BAR_HEIGHT_PX;
    return {
        leftPx,
        rightPx: leftPx + widthPx,
        centerPx,
        widthPx,
        topPx,
        bottomPx,
        centerY: topPx + ((bottomPx - topPx) / 2),
    };
};

const countGanttWorkDaysBetween = (startValue, endValue, config = {}) => {
    const start = shiftToGanttLaborableDate(startValue, config, 1);
    const end = shiftToGanttLaborableDate(endValue, config, 1);
    if (!start || !end) return 0;
    if (end.getTime() === start.getTime()) return 0;
    const step = end > start ? 1 : -1;
    let cursor = new Date(start);
    let count = 0;
    let guard = 0;
    while (cursor.getTime() !== end.getTime() && guard < 10000) {
        cursor.setDate(cursor.getDate() + step);
        if (isGanttLaborableDate(cursor, config)) count += step;
        guard += 1;
    }
    return count;
};

const buildGanttPlanningAnalysis = (rows = [], drafts = {}, config = {}) => {
    const calculable = rows.filter((row) => row.is_calculable);
    const dated = calculable
        .map((row) => {
            const id = String(row.budget_line_id);
            const draft = drafts[id] || {};
            const start = shiftToGanttLaborableDate(draft.start_date || row.start_date, config, 1);
            return start ? { row, draft, id, start } : null;
        })
        .filter(Boolean);
    if (!dated.length) return new Map();

    const projectStart = dated.reduce((acc, item) => (item.start < acc ? item.start : acc), dated[0].start);
    const nodes = new Map();
    const outgoing = new Map();
    const incoming = new Map();

    dated.forEach(({ row, draft, id, start }) => {
        const duration = getGanttRowDuration(row, draft);
        const es = countGanttWorkDaysBetween(projectStart, start, config);
        nodes.set(id, {
            id,
            row,
            draft,
            duration,
            isMilestone: isGanttMilestone(row, draft),
            es,
            ef: es + duration,
            ls: null,
            lf: null,
            totalSlack: 0,
            freeSlack: 0,
            criticalOutgoingKeys: [],
            criticalIncomingKeys: [],
        });
        outgoing.set(id, []);
        incoming.set(id, []);
    });

    nodes.forEach((node, targetId) => {
        normalizeRowDependencies(node.row, node.draft).forEach((dependency) => {
            const sourceId = String(dependency.source_id);
            if (!nodes.has(sourceId) || sourceId === targetId) return;
            const edge = { sourceId, targetId, dependency };
            outgoing.set(sourceId, [...(outgoing.get(sourceId) || []), edge]);
            incoming.set(targetId, [...(incoming.get(targetId) || []), edge]);
        });
    });

    const indegree = new Map(Array.from(nodes.keys()).map((id) => [id, incoming.get(id)?.length || 0]));
    const queue = Array.from(indegree.entries())
        .filter(([, degree]) => degree === 0)
        .map(([id]) => id);
    const topo = [];
    while (queue.length) {
        const current = queue.shift();
        topo.push(current);
        (outgoing.get(current) || []).forEach((edge) => {
            const nextDegree = (indegree.get(edge.targetId) || 0) - 1;
            indegree.set(edge.targetId, nextDegree);
            if (nextDegree === 0) queue.push(edge.targetId);
        });
    }
    if (topo.length !== nodes.size) return new Map();

    const targetStartConstraint = (source, target, dependency) => {
        const lag = dependencyLagToDays(dependency, config, { sourceNode: source });
        const type = normalizeDependencyType(dependency?.type);
        if (type === 'SS') return source.es + lag;
        if (type === 'FF') return source.ef + lag - target.duration;
        if (type === 'SF') return source.es + lag - target.duration;
        return source.ef + lag;
    };

    topo.forEach((id) => {
        const target = nodes.get(id);
        (incoming.get(id) || []).forEach((edge) => {
            const source = nodes.get(edge.sourceId);
            if (!source || !target) return;
            const constrainedStart = targetStartConstraint(source, target, edge.dependency);
            target.es = Math.max(target.es, constrainedStart);
            target.ef = target.es + target.duration;
        });
    });

    const projectFinish = Math.max(...Array.from(nodes.values()).map((node) => node.ef));
    nodes.forEach((node) => {
        node.lf = projectFinish;
        node.ls = projectFinish - node.duration;
    });

    [...topo].reverse().forEach((id) => {
        const source = nodes.get(id);
        if (!source) return;
        (outgoing.get(id) || []).forEach((edge) => {
            const target = nodes.get(edge.targetId);
            if (!target) return;
            const lag = dependencyLagToDays(edge.dependency, config, { sourceNode: source });
            const type = normalizeDependencyType(edge.dependency?.type);
            let candidateLf = source.lf;
            if (type === 'SS') candidateLf = target.ls - lag + source.duration;
            else if (type === 'FF') candidateLf = target.lf - lag;
            else if (type === 'SF') candidateLf = target.lf - lag + source.duration;
            else candidateLf = target.ls - lag;
            source.lf = Math.min(source.lf, candidateLf);
            source.ls = source.lf - source.duration;
        });
    });

    nodes.forEach((node) => {
        const successorEdges = outgoing.get(node.id) || [];
        const freeSlackLimit = successorEdges.length
            ? Math.min(...successorEdges.map((edge) => {
                const target = nodes.get(edge.targetId);
                if (!target) return projectFinish;
                return targetStartConstraint(node, target, edge.dependency);
            }))
            : projectFinish;
        node.totalSlack = Math.max(0, roundConfigNumber((node.ls ?? 0) - node.es, 4));
        node.freeSlack = Math.max(0, roundConfigNumber(freeSlackLimit - node.ef, 4));
    });

    const { criticalOutgoingByNode, criticalIncomingByNode } = resolveCriticalEdgeKeys({
        nodes,
        outgoing,
        targetStartConstraint,
        tolerance: 0.0001,
    });
    nodes.forEach((node, nodeId) => {
        node.criticalOutgoingKeys = criticalOutgoingByNode.get(String(nodeId)) || [];
        node.criticalIncomingKeys = criticalIncomingByNode.get(String(nodeId)) || [];
    });

    return nodes;
};

const isPlanningNodeCritical = (node = null) => Boolean(node && Number(node.totalSlack) <= 0.0001);

const isPlanningNodeCriticalPathMember = (node = null) => Boolean(
    isPlanningNodeCritical(node)
    && (
        (Array.isArray(node?.criticalOutgoingKeys) && node.criticalOutgoingKeys.length > 0)
        || (Array.isArray(node?.criticalIncomingKeys) && node.criticalIncomingKeys.length > 0)
        || (Array.isArray(node?.criticalPathIndexes) && node.criticalPathIndexes.length > 0)
    )
);

const buildInteractionDraft = (interaction, dayDelta, config = {}) => {
    if (!interaction?.originalStartDate) return null;

    if (interaction.type === 'move') {
        if (interaction.manualMilestonePreview?.milestoneDraft) {
            return interaction.manualMilestonePreview.milestoneDraft;
        }
        const nextStart = shiftDateByDays(interaction.originalStartDate, dayDelta, config);
        if (!nextStart) return null;
        return {
            start_date: toNativeDateTimeValue(nextStart, config, 'start'),
            duration: interaction.originalDuration,
        };
    }

    if (interaction.type === 'resize-end') {
        return {
            start_date: toNativeDateTimeValue(interaction.originalStartDate, config, 'start'),
            duration: Math.max(1, interaction.originalDuration + dayDelta),
        };
    }

    if (interaction.type === 'resize-start') {
        const clampedDelta = Math.min(dayDelta, interaction.originalDuration - 1);
        const nextStart = shiftDateByDays(interaction.originalStartDate, clampedDelta, config);
        if (!nextStart) return null;
        return {
            start_date: toNativeDateTimeValue(nextStart, config, 'start'),
            duration: Math.max(1, interaction.originalDuration - clampedDelta),
        };
    }

    return null;
};

const resolveManualMilestoneMovePreview = ({
    interaction = null,
    pixelDelta = 0,
    timelineSegments = [],
    segmentColumnWidth = 0,
    timelineWidth = 0,
    config = {},
} = {}) => {
    if (
        !interaction
        || interaction.type !== 'move'
        || !interaction.isManualMilestoneDrag
        || interaction.interactionScope !== 'task'
        || !interaction.originalStartDate
        || !timelineSegments.length
    ) {
        return null;
    }

    const width = Math.max(1, Number(timelineWidth || getTimelineWidthPx(timelineSegments, segmentColumnWidth) || 1));
    const originalStartPx = Number(interaction.originalStartPx || 0);
    const rawPixelDelta = Number(pixelDelta || 0);
    const maxTrustedDeltaPx = Math.max(24, Math.min(width, Number(interaction.containerWidth || width || 0)));
    const boundedPixelDelta = clamp(rawPixelDelta, -maxTrustedDeltaPx, maxTrustedDeltaPx);
    const pointerStartPx = clamp(originalStartPx + boundedPixelDelta, 0, width);
    const rawPointerDate = getTimelineDateFromPx(pointerStartPx, timelineSegments, segmentColumnWidth);
    if (!rawPointerDate) return null;

    const direction = boundedPixelDelta < 0 ? -1 : 1;
    const snappedStartDate = interaction.snapManualMilestoneToWorkdayStart
        ? (shiftToGanttLaborableDate(rawPointerDate, config, direction)
            || applyGanttWorkdayStartTime(rawPointerDate, config)
            || rawPointerDate)
        : (shiftToGanttWorkingDateTime(rawPointerDate, config, direction) || rawPointerDate);
    const projectStartDate = shiftToGanttWorkingDateTime(config?.fecha_inicio_proyecto, config, 1);
    const minimumPolicyDate = normalizeDate(interaction.minimumAllowedStartDate);
    const maximumPolicyDate = normalizeDate(interaction.maximumAllowedStartDate);
    const minStartDate = [projectStartDate, minimumPolicyDate]
        .filter(Boolean)
        .reduce((latest, item) => (!latest || item > latest ? item : latest), null);
    let effectiveStartDate = new Date(snappedStartDate);

    if (minStartDate && effectiveStartDate < minStartDate) {
        effectiveStartDate = new Date(minStartDate);
    }
    if (maximumPolicyDate && effectiveStartDate > maximumPolicyDate) {
        effectiveStartDate = new Date(maximumPolicyDate);
    }

    const milestoneStartValue = toNativeDateTimeValue(effectiveStartDate, config, 'start');
    const milestoneStartDate = normalizeDate(milestoneStartValue) || effectiveStartDate;
    const effectiveStartPx = clamp(
        getDatePositionPx(milestoneStartDate, timelineSegments, segmentColumnWidth),
        0,
        width,
    );
    const effectiveLaborDelta = countGanttWorkDurationDaysBetween(
        interaction.originalStartDate,
        milestoneStartDate,
        config,
    );
    const milestoneDraft = {
        start_date: milestoneStartValue,
        end_date: milestoneStartValue,
        duration: 0,
    };

    return {
        originalStartDate: interaction.originalStartDate,
        rawPointerDate,
        snappedStartDate,
        effectiveStartDate: milestoneStartDate,
        effectiveStartPx,
        effectiveLaborDelta,
        translationPx: effectiveStartPx - originalStartPx,
        boundedPixelDelta,
        milestoneDraft,
    };
};

const normalizePreviewCommitDateValue = (value, config = {}) => {
    const parsed = normalizeDate(value);
    return parsed ? toNativeDateTimeValue(parsed, config, 'start') : '';
};

const normalizePreviewCommitPatchMap = (patches = {}, config = {}) => {
    const normalized = {};
    Object.entries(patches || {})
        .sort(([left], [right]) => String(left).localeCompare(String(right)))
        .forEach(([lineId, patch]) => {
            if (!patch || typeof patch !== 'object') return;
            normalized[String(lineId)] = {
                start_date: normalizePreviewCommitDateValue(patch.start_date, config),
                end_date: normalizePreviewCommitDateValue(patch.end_date, config),
                duration: Number(Number(patch.duration ?? 0).toFixed(6)),
                dependencies: Array.isArray(patch.dependencies)
                    ? patch.dependencies.map((dependency) => ({
                        source_id: normalizeDependencyEndpointId(dependency?.source_id),
                        target_id: normalizeDependencyEndpointId(dependency?.target_id),
                        type: normalizeDependencyType(dependency?.type),
                        lag_days: Number(Number(dependency?.lag_days || 0).toFixed(6)),
                        lag_unit: normalizeDependencyLagUnit(dependency?.lag_unit || 'day'),
                    }))
                    : null,
            };
        });
    return normalized;
};

const previewCommitPatchMapsMatch = (previewPatches = {}, commitPatches = {}, config = {}) => (
    JSON.stringify(normalizePreviewCommitPatchMap(previewPatches, config))
    === JSON.stringify(normalizePreviewCommitPatchMap(commitPatches, config))
);

