            totalAmount: accumulator.totalAmount + Number(segment?.amount || 0),
            interparentMergeCount: accumulator.interparentMergeCount + (String(segment?.source || '').trim().toLowerCase() === 'gantt_interparent_merge' ? 1 : 0),
