        if (!hasDistribution) return false;
        const startsAt = selectedTaskDraft?.start_date || selectedTaskRow?.start_date || resolveVisibleRowStartDate(selectedTaskRow, configDraft);
        const endsAt = selectedTaskDraft?.end_date || selectedTaskRow?.end_date || startsAt;
