        const acceptedCount = selectedTaskSubbars.filter((segment) => String(segment?.status || '').trim().toLowerCase() === 'accepted_session').length;
        const interparentMergeCount = selectedTaskSubbars.filter((segment) => String(segment?.source || '').trim().toLowerCase() === 'gantt_interparent_merge').length;
