        const selectedIdSet = new Set(selectedTaskSelectedSubbars.map((segment) => String(segment?.id || '')).filter(Boolean));
        const nextSubbars = selectedTaskSubbars
            .filter((segment) => !selectedIdSet.has(String(segment?.id || '')))
