            const wheelDirection = event.deltaY < 0 ? 1 : -1;
            const intensity = clamp(Math.abs(event.deltaY || 0) / 180, 0.75, 2.5);
            const baseZoom = pendingZoomTargetLevelRef.current ?? zoomLevel;
            const nextZoom = normalizeZoomLevel(baseZoom + (wheelDirection * 0.04 * intensity));
            scheduleBufferedZoomTargetLevel(nextZoom);
