        const targetIndex = orderedRows.findIndex((candidate) => String(resolveRowLineId(candidate) || '').trim() === normalizedTargetLineId);
        if (targetIndex < 0) {
            return { canMove: false, reason: 'No se pudo resolver la posición de destino del hito.' };
        }
        const nextDisplayAnchorId = placement === 'before'
            ? (targetIndex > 0 ? String(resolveRowLineId(orderedRows[targetIndex - 1]) || '').trim() : MANUAL_MILESTONE_START_SENTINEL)
            : normalizedTargetLineId;
