                                            optionClassName="min-h-[46px] border border-white/8 !bg-white/[0.035] px-3 text-[10px] font-black uppercase tracking-[0.12em] !text-white/84 hover:border-[#F39200]/30 hover:!bg-white/[0.07] hover:!text-white"
                                            optionSelectedClassName="min-h-[46px] border border-[#F39200]/45 !bg-[#173247] px-3 text-[10px] font-black uppercase tracking-[0.12em] !text-white shadow-[inset_2px_2px_6px_rgba(0,0,0,0.28),inset_-2px_-2px_6px_rgba(255,255,255,0.04)]"
                                            optionDisabledClassName="!text-white/28"
