                                const summary = compareDialog.summary || {};
                                const moneyCurrency = summary.costCurrency || 'USD';
                                const moneyDecimals = summary.costDecimals ?? 2;
                                const formatSignedMoney = (value) => {
                                    const numeric = Number(value || 0);
                                    const sign = numeric > 0 ? '+' : numeric < 0 ? '-' : '';
                                    return `${sign}${formatCurrency(Math.abs(numeric), moneyCurrency, moneyDecimals)}`;
                                };
                                const entries = [
                                    { label: 'Tareas modificadas', value: summary.apus || 0, tone: 'default' },
                                    { label: 'Tareas con recursos ajustados', value: summary.resourceApus || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Recursos ajustados', value: formatNumber(summary.resourceUnitsTotal || 0, 2), tone: 'default', active: Math.abs(Number(summary.resourceUnitsTotal || 0)) > 0.0001 },
                                    { label: 'Líneas con subbarras', value: summary.subbarRows || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Tramos modificados', value: summary.subbarCount || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Tramos en borrador', value: summary.draftSubbarCount || 0, tone: 'warning', hideWhenZero: true },
                                    { label: 'Ventanas manuales', value: summary.manualTemporalRows || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Tanteos CPM', value: summary.cpmReconciledRows || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Fusiones entre tramos', value: summary.interparentMergeCount || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Líneas con conflicto', value: summary.valuadoConflictRows || 0, tone: 'warning', hideWhenZero: true },
                                    { label: 'Períodos excedidos', value: summary.valuadoConflictPeriods || 0, tone: 'warning', hideWhenZero: true },
                                    { label: 'Tareas con impacto económico', value: summary.costApus || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Δ presupuesto visible', value: formatSignedMoney(summary.costTotalDelta || 0), tone: 'success', active: Math.abs(Number(summary.costTotalDelta || 0)) > 0.0001 },
                                    { label: 'Δ temporal visible', value: formatSignedMoney(summary.costTemporalDelta || 0), tone: 'success', active: Math.abs(Number(summary.costTemporalDelta || 0)) > 0.0001 },
                                    { label: 'Δ duración agregada', value: `${formatNumber(summary.costDurationDelta || 0, 2)} d`, tone: 'success', active: Math.abs(Number(summary.costDurationDelta || 0)) > 0.0001 },
                                    { label: 'Ajustes RR', value: summary.conflictReliefSessionCount || 0, tone: 'default', hideWhenZero: true },
                                    { label: 'Días recolocados RR', value: `${formatNumber(summary.conflictReliefMovedDays || 0, 2)} d`, tone: 'default', active: Math.abs(Number(summary.conflictReliefMovedDays || 0)) > 0.0001 },
                                ].filter((entry) => {
                                    if (typeof entry.active === 'boolean') return entry.active;
                                    if (entry.hideWhenZero) return Number(entry.value || 0) > 0;
                                    return true;
                                });

                                const visibleEntries = entries.length
